  const resetAll = () => {
    change.reset();
    reassign.reset();
    resettle.reset();
    defer.reset();
    proof.reset();
    split.reset();
    redate.reset();
    lock.reset();
    remind.reset();
    waive.reset();
    hold.reset();
    inline.reset();
    comment.reset();
    line.reset();
    setRefused(undefined);
  };
