        onClick={() => {
          change.reset();
          resettle.reset();
          defer.reset();
          proof.reset();
          split.reset();
          redate.reset();
          lock.reset();
          remind.reset();
    waive.reset();
          waive.reset();
          hold.reset();
          inline.reset();
          comment.reset();
          line.reset();
          setRefused(undefined);
          reassign.mutate(moveTo);
        }}
      >
        Move
      </button>{' '}
      <button
        type="button"
        data-testid="claim-resettle"
        disabled={busy}
        onClick={() => {
          change.reset();
          reassign.reset();
          defer.reset();
          proof.reset();
          split.reset();
          redate.reset();
          lock.reset();
          remind.reset();
    waive.reset();
          waive.reset();
          hold.reset();
          inline.reset();
          comment.reset();
          line.reset();
          setRefused(undefined);
          resettle.mutate();
        }}
      >
        Re-settle
      </button>{' '}
      Deferred <span data-testid="claim-deferred">{claim.deferred ? 'yes' : 'no'}</span>{' '}
