          reassign.reset();
          resettle.reset();
          defer.reset();
          split.reset();
          redate.reset();
          lock.reset();
          remind.reset();
    waive.reset();
          waive.reset();
          hold.reset();
          inline.reset();
          comment.reset();
          line.reset();
          setRefused(undefined);
          proof.mutate(proofKind);
        }}
      >
        Add proof
      </button>{' '}
