        data-testid="claim-split"
        disabled={busy}
        onClick={() => {
          change.reset();
          reassign.reset();
          resettle.reset();
          defer.reset();
          proof.reset();
          redate.reset();
          lock.reset();
          remind.reset();
    waive.reset();
          waive.reset();
          hold.reset();
          inline.reset();
          comment.reset();
          line.reset();
          setRefused(undefined);
