          hold.reset();
          inline.reset();
          comment.reset();
          line.reset();
          setRefused(undefined);
          redate.mutate(newDate);
        }}
      >
        Re-date
      </button>{' '}
      Reminded <span data-testid="claim-reminded">{claim.reminded ?? ''}</span>{' '}

